  def inline_svg_icon(name, **opts)
    svg = ICONS[name.to_s] || ICONS["form"]
    svg.html_safe
  end

  def status_badge(status)
    map = {
      "pending"  => ["badge",              "待审核"],
      "approved" => ["badge badge-success badge-dot", "已通过"],
      "rejected" => ["badge badge-danger badge-dot",  "已拒绝"],
      "live"     => ["badge badge-success badge-dot", "进行中"],
      "draft"    => ["badge",              "草稿"],
      "ended"    => ["badge",              "已结束"],
      "closed"   => ["badge",              "已关闭"],
      "upcoming" => ["badge badge-info",   "即将开始"],
      "past"     => ["badge",              "已结束"],
      "reviewing"=> ["badge badge-warn",   "审核中"],
    }
    css, label = map[status.to_s] || ["badge", status]
    content_tag(:span, label, class: css)
  end
